    excluded = {str(Path(x['path'])) for x in (_STAGE_REVIEW_PIN,_STAGE_FULL_PROOF_PIN,_STAGE_ADOPTION_PIN)}|set(output_paths)
    return [dict(path=path,sha256=OBSERVATIONS[path]['sha256'],bytes=OBSERVATIONS[path]['bytes'])
        for path in sorted(OBSERVATIONS) if path not in excluded]

def _stage_output_paths(stage,role,rows):
    paths = []
    for r in _stage_roles(stage,role):
        draft = absolute(rows[r]['draft_path'])
        paths.extend((str(draft),str(_stage_receipt_path(r)),str(HERE/'source_diffs'/(draft.name+'.diff'))))
    need(len(paths) == len(set(paths)), 'exact distinct internally derived stage Source/diff/receipt paths')
